// Des: Tests car store: upsert, price history, hash, cluster, gone
// Flo: temp db > save cars > read rows back > assert
// I/O: Car structs > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const inde = @import("st-page-inde.zig"); const stor = @import("st-carz-stor.zig"); const typz = @import("pa-carz-type.zig");
const NOWZ: i64 = 1_795_600_000_000; const DAYZ: i64 = 86_400_000;
fn opnz(tmpz: *std.testing.TmpDir, buff: *[160]u8) !@import("st-stor-sqli.zig").Dbzz { const dirz = try std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); return inde.pageOpen(std.testing.allocator, std.testing.io, dirz); }
fn scal(dbzz: *@import("st-stor-sqli.zig").Dbzz, sqlz: [:0]const u8) !i64 { var stmt = try dbzz.prep(sqlz); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
fn mkzz(urlz: []const u8, pric: i64) typz.Carz { return .{ .urlz = urlz, .site = "x.vn", .lidz = "1", .make = "Toyota", .modl = "Fortuner", .year = 2017, .cond = "used", .kmzz = 84281, .pric = pric, .prov = "Bình Dương", .gear = "MT", .powr = "DSL", .phon = "0966 353 678" }; }
test "save: insert, same, update; price history only on change; a missing price never erases the old one" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); try std.testing.expectEqual(stor.Svre.news, try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 520_000_000), "h1", NOWZ)); try std.testing.expectEqual(stor.Svre.same, try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 520_000_000), "h1", NOWZ + DAYZ)); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carp;")); try std.testing.expectEqual(stor.Svre.chan, try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 500_000_000), "h2", NOWZ + 2 * DAYZ)); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carp;")); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 0), "h3", NOWZ + 3 * DAYZ); try std.testing.expectEqual(@as(i64, 500_000_000), try scal(&dbzz, "SELECT pric FROM carz;")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carp;")); try std.testing.expectEqual(@as(i64, NOWZ), try scal(&dbzz, "SELECT fors FROM carz;")); try std.testing.expectEqual(@as(i64, NOWZ + 3 * DAYZ), try scal(&dbzz, "SELECT lasz FROM carz;")); }
test "phone: digits kept for now, hash is stable and not the number, salt persists" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 5_000_000_00), "h1", NOWZ); _ = try stor.carzSave(&stoz, mkzz("https://y.vn/b-2", 5_000_000_00), "h2", NOWZ); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(DISTINCT phsh) FROM carz WHERE phsh<>'';")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carz WHERE phon='0966353678' AND phsh<>'0966353678' AND length(phsh)=16;")); const sto2 = try stor.storOpen(&dbzz, NOWZ + 5); try std.testing.expectEqual(stoz.salt, sto2.salt); }
test "cluster: look-alike cars share an id, new cars and unknown models get none" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); var onez = mkzz("https://x.vn/a-1", 500_000_000); onez.phon = ""; var twoz = mkzz("https://y.vn/b-2", 500_000_000); twoz.phon = ""; twoz.kmzz = 86000; var thrz = mkzz("https://z.vn/c-3", 500_000_000); thrz.phon = ""; thrz.kmzz = 130000; var neuz = mkzz("https://n.vn/d-4", 500_000_000); neuz.cond = "new"; var unkz = mkzz("https://u.vn/e-5", 500_000_000); unkz.make = ""; for ([_]typz.Carz{ onez, twoz, thrz, neuz, unkz }) |carz| _ = try stor.carzSave(&stoz, carz, "h", NOWZ); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(DISTINCT clus) FROM carz WHERE clus<>'';")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carz WHERE clus='';")); }
test "gone: 404 pages, dead rows, sold notice; a row seen again comes back alive" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 500_000_000), "h", NOWZ); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-2", 500_000_000), "h", NOWZ - 100 * DAYZ); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-3", 500_000_000), "h", NOWZ); try dbzz.exec("INSERT INTO page(urlz,hexz,etag,lmod,code,tier,vend,fetc,next) VALUES('https://x.vn/a-1','h','','',404,1,'',1,1);"); try std.testing.expectEqual(@as(u32, 1), try stor.goneHttp(&stoz, NOWZ)); try std.testing.expectEqual(@as(u32, 1), try stor.goneDead(&stoz, NOWZ, 90 * DAYZ)); try stor.goneMark(&stoz, "https://x.vn/a-3", NOWZ, "page"); try std.testing.expectEqual(@as(i64, 3), try scal(&dbzz, "SELECT count(*) FROM carz WHERE stat=1;")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE grsn='http';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE grsn='vani';")); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-3", 500_000_000), "h", NOWZ + DAYZ); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT stat FROM carz WHERE urlz='https://x.vn/a-3';")); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT gone FROM carz WHERE urlz='https://x.vn/a-3';")); }
